<script setup>
import { ref,onMounted,computed } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useLearning } from '../store'
import SafeMarkdown from '../components/SafeMarkdown.vue'
const store=useLearning(),route=useRoute(),router=useRouter()
const conversations=ref([]),current=ref(null),message=ref(''),mode=ref('rag'),busy=ref(false),status=ref(null),source=ref(null),saved=ref({}),waiting=ref(''),retryKey=ref('')
const suggestions=['根据我最近的错题，帮我安排三天复习。','我现在适合学习函数极值吗？','为什么推荐我先练导数计算？']
async function refreshList(){conversations.value=await store.api('/assistant/conversations');status.value=await store.api('/assistant/status')}
async function select(id){current.value=await store.api(`/assistant/conversations/${id}`);source.value=null;retryKey.value=''}
async function create(context={}){const c=await store.api('/assistant/conversations',{method:'POST',body:JSON.stringify({title:'新的学习对话',...context})});await refreshList();await select(c.id)}
async function remove(id){await store.run(async()=>{await store.api(`/assistant/conversations/${id}`,{method:'DELETE'});if(current.value?.id===id)current.value=null;await refreshList()})}
async function endAssessment(){await store.run(async()=>{await store.api('/assistant/assessment/end',{method:'POST'});await refreshList()})}
async function send(){if(!message.value.trim()||busy.value)return;busy.value=true;waiting.value=mode.value==='agent'?'正在查看学习资料并整理建议…':'正在检索资料并生成回答…';
  await store.run(async()=>{if(!current.value)await create();if(!retryKey.value)retryKey.value=crypto.randomUUID();
    const answer=await store.api(`/assistant/conversations/${current.value.id}/messages`,{method:'POST',body:JSON.stringify({message:message.value,request_key:retryKey.value,mode:mode.value})});
    await select(current.value.id);message.value='';retryKey.value='';await refreshList()
  });busy.value=false;waiting.value=''
}
async function openSource(id){source.value=null;await store.run(async()=>{source.value=await store.api(`/assistant/sources/${id}`)})}
async function save(turn){return await store.run(async()=>{const p=await store.api('/assistant/plans',{method:'POST',body:JSON.stringify({turn_id:turn.id,request_key:`plan-${turn.id}`})});saved.value[turn.id]=p.id;return p.id})}
async function practice(turn,day,task){const pid=saved.value[turn.id]||await save(turn);if(!pid)return;await store.run(async()=>{const r=await store.api(`/assistant/plans/${pid}/practice`,{method:'POST',body:JSON.stringify({day,task})});router.push(`/practice?session=${r.session_id}`)})}
onMounted(()=>store.run(async()=>{await refreshList();if(route.query.knowledge||route.query.question){await create({knowledge_id:route.query.knowledge||null,question_id:route.query.question?Number(route.query.question):null,title:route.query.question?'题目讲解':`${store.name(route.query.knowledge)} · 提问`});message.value=route.query.question?'请根据我的作答讲解这道题，指出思路与易错点。':`请讲解${store.name(route.query.knowledge)}的关键思路和易错点。`}else if(conversations.value.length)await select(conversations.value[0].id)}))
</script>
<template>
<div class="page-heading"><div><p class="eyebrow">知序 · {{ store.currentCourse?.name }}</p><h1>有依据地问，循着思路学</h1><p>结合本课程资料与自己的学习记录，理解知识、安排下一步。</p></div><span class="badge">{{ status?.mode==='mock'?'测试 Mock · 非真实模型':'模型问答' }}</span></div>
<div v-if="status&&!status.configured" class="callout">模型尚未配置。可查看已有对话；请管理员在服务端配置 API Key 后使用真实问答，本系统不会用模拟回答代替。</div>
<div v-if="status?.assessment_open" class="callout">当前存在未提交练习，助手仅提供一般提示。完成练习后可详细讲解。<button class="text-button" @click="endAssessment">结束未完成练习，继续学习辅导</button></div>
<div class="assistant-layout"><aside class="chat-history"><button class="primary wide" :disabled="busy" @click="store.run(()=>create())">＋ 新建对话</button><div v-for="c in conversations" :key="c.id" class="history-item" :class="{active:current?.id===c.id}"><button :disabled="busy" @click="store.run(()=>select(c.id))">{{ c.title }}</button><button :disabled="busy" class="delete-chat" @click="remove(c.id)" :aria-label="`删除对话 ${c.title}`">×</button></div><p>对话仅自己可见。计划先生成草稿，点击保存后才入库。</p></aside>
<section class="chat-main"><div class="chat-messages" aria-live="polite"><div v-if="!current?.turns?.length" class="assistant-welcome"><span>✧</span><h2>把不理解的那一步说出来</h2><p>知识问答提供原文引用；学习建议会查询你的掌握度与先修缺口。</p><button v-for="s in suggestions" :key="s" @click="message=s;mode='agent'">{{ s }}</button></div>
<article v-for="turn in current?.turns||[]" :key="turn.id" class="chat-turn"><div class="student-message">{{ turn.question }}</div><div class="assistant-answer"><small>{{ turn.provider_mode==='mock'?'测试 Mock 输出':turn.origin==='model'?'学习助手':'学习提示' }}<span v-if="turn.status==='failed'"> · 本次未完成</span></small><SafeMarkdown :text="turn.answer"/><div class="citation-cards"><button v-for="citation in turn.citations" :key="citation.chunk_id" @click="openSource(citation.chunk_id)"><span>▤ {{ citation.title }}</span><small>{{ citation.source }}{{ citation.page?' · 第 '+citation.page+' 页':'' }}</small></button></div>
<details v-if="turn.diagnostics" class="execution-details"><summary>执行记录（不代表回答质量）</summary><p>耗时 {{ turn.diagnostics.elapsed_ms ?? '未知' }} ms · 模型轮次 {{ turn.diagnostics.model_calls ?? '未知' }} · HTTP 尝试 {{ turn.diagnostics.provider_attempts ?? '未知' }}</p><p>Token：{{ turn.diagnostics.usage ? `输入 ${turn.diagnostics.usage.input_tokens} / 输出 ${turn.diagnostics.usage.output_tokens}` : '未知（提供方未返回完整用量）' }}</p><ul><li v-for="(tool,index) in turn.tools" :key="index">{{ tool.name }} · {{ tool.status==='success'?'执行成功':'执行失败／降级' }} · {{ tool.elapsed_ms }} ms</li></ul></details><section v-if="turn.plan" class="study-plan"><div class="section-heading"><h3>{{ turn.plan.content.goal }}</h3><span class="badge">草稿 · {{ turn.plan.origin==='model'?'模型建议':'规则降级建议' }}</span></div><p>预计时间为估算；先修不满足的任务需先通过前置知识点。</p><div v-for="day in turn.plan.content.days" :key="day.day" class="plan-day"><strong>第 {{ day.day }} 天</strong><div v-for="(task,index) in day.tasks" :key="index"><h4>{{ store.name(task.knowledge_id) }} · {{ task.question_count }} 题 · 约 {{ task.estimated_minutes }} 分钟</h4><p>{{ task.reason }}</p><small v-if="task.conditional_on_pass">需先修通过后开始</small><button class="secondary" @click="practice(turn,day.day,index)">开始练习</button></div></div><p class="muted">依据：{{ turn.plan.content.basis.join('；') }}</p><button class="primary" @click="save(turn)">{{ saved[turn.id]?'计划已保存':'保存计划' }}</button></section></div></article>
<div v-if="busy" class="callout" role="status">{{ waiting }}</div></div>
<form class="chat-composer" @submit.prevent="send"><label>你的问题<textarea v-model="message" :disabled="busy" maxlength="2000" rows="3" placeholder="例如：求极值时，为什么导数等于零还不够？" @input="retryKey=''"/></label><div><label class="chat-mode">回答方式<select v-model="mode" :disabled="busy"><option value="rag">知识库问答</option><option value="agent">结合我的学习记录</option></select></label><button class="primary" :disabled="busy||!message.trim()">{{ busy?'正在回答…':'发送问题' }}</button></div><small>只读学习工具，不会修改成绩。回答有误时以原始资料和服务端判题为准。</small></form></section></div>
<div v-if="source" class="source-overlay" @click.self="source=null"><section role="dialog" aria-modal="true" aria-label="引用原文" class="source-dialog"><button class="text-button" @click="source=null">关闭原文 ×</button><h2>{{ source.title }}</h2><p>{{ source.source }} · 版本 {{ source.version }} · {{ source.chapter }}</p><SafeMarkdown :text="source.content"/><small>{{ source.chunk_id }}</small></section></div>
</template>
<style scoped>
.assistant-layout{display:grid;grid-template-columns:225px minmax(0,1fr);gap:20px;align-items:start}.chat-history{background:white;border:1px solid var(--border);border-radius:10px;padding:18px;max-height:720px;overflow:auto}.chat-history>p{font-size:11px;margin-top:22px}.history-item{display:flex;margin-top:10px;border-radius:6px}.history-item.active{background:var(--light)}.history-item button{border:0;background:none;color:var(--purple);text-align:left;font-size:12px;padding:10px;overflow-wrap:anywhere}.history-item button:first-child{flex:1}.chat-main{border:1px solid var(--border);background:white;border-radius:12px;overflow:hidden}.chat-messages{padding:26px;max-height:750px;min-height:370px;overflow:auto}.assistant-welcome{padding:25px 5px}.assistant-welcome>span{font-size:40px;color:var(--purple)}.assistant-welcome p{font-size:12px}.assistant-welcome button{display:block;background:#f8f7fc;color:var(--purple);border:1px solid var(--border);padding:12px;margin-top:10px;border-radius:6px;text-align:left}.student-message{background:var(--light);padding:15px 18px;margin:0 0 20px auto;border-radius:10px 10px 0 10px;max-width:90%;white-space:pre-wrap}.assistant-answer>small{display:block;color:var(--muted);margin-bottom:12px}.chat-turn{margin-bottom:35px}.citation-cards{display:flex;gap:8px;flex-wrap:wrap}.citation-cards button{border:1px solid var(--border);border-radius:7px;padding:10px 13px;background:#fbfaff;color:var(--purple);text-align:left;max-width:100%}.citation-cards span,.citation-cards small{display:block}.citation-cards small{font-size:10px;color:var(--muted)}.chat-composer{padding:20px;border-top:1px solid var(--border);background:#fbfaff}.chat-composer>div{display:flex;justify-content:space-between;align-items:center;gap:10px}.chat-composer>small{font-size:10px;color:var(--muted);display:block;margin-top:12px}.chat-mode{flex-direction:row;align-items:center;margin:0;white-space:nowrap}.chat-mode select{min-height:35px;padding:6px}.study-plan{padding:20px;border:1px solid #d7d0ee;background:#fcfbff;border-radius:9px;margin-top:20px}.study-plan>p{font-size:11px}.plan-day{padding:15px 0;border-bottom:1px solid var(--border)}.plan-day>strong{color:var(--purple)}.plan-day h4{margin:10px 0;font-size:13px}.plan-day p{font-size:12px}.plan-day .secondary{padding:6px 12px;font-size:11px}.source-overlay{position:fixed;inset:0;background:#29263f66;z-index:30;display:flex;align-items:center;justify-content:center;padding:25px}.source-dialog{background:white;padding:30px;border-radius:12px;width:720px;max-width:100%;max-height:85vh;overflow:auto}.source-dialog>.text-button{float:right}.source-dialog>small{font-size:10px;color:var(--muted)}
@media(max-width:800px){.assistant-layout{grid-template-columns:1fr}.chat-history{max-height:170px}.chat-history>p{display:none}.chat-messages{padding:16px}.chat-composer>div{align-items:stretch;flex-direction:column}.chat-mode{font-size:11px}.source-dialog{padding:20px}}
</style>
